// 8BitDo prints Nintendo's faces with Sony's shoulders and sticks.
function paths(style, slot) {
    var table = PROMPTS[style] || PROMPTS.xbox;
    if (style === "eightbitdo" && !table[slot])
        table = PROMPTS.nintendo;
    return table[slot] || null;
}
